const allIssues = $input.all().flatMap(item => item.json.issues || []);
const excludeTypes = ['sub-task', 'subtarea', 'epic', 'epica'];
const issues = allIssues.filter(issue => {
  const typeName = (issue.fields.issuetype ? issue.fields.issuetype.name : '').toLowerCase();
  return !excludeTypes.includes(typeName);
});
const fecha = new Date().toLocaleString('es-CL', { timeZone: 'America/Santiago' });
const total = issues.length;
const now = new Date();

const formatCreated = (iso) => {
  if (!iso) return '-';
  const d = new Date(iso);
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const yyyy = d.getFullYear();
  const diffMs = now - d;
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
  let ago;
  if (diffDays === 0) ago = 'hoy';
  else if (diffDays === 1) ago = 'ayer';
  else if (diffDays < 30) ago = 'hace ' + diffDays + ' dias';
  else if (diffDays < 365) ago = 'hace ' + Math.floor(diffDays / 30) + ' meses';
  else ago = 'hace ' + Math.floor(diffDays / 365) + ' a\u00F1o' + (Math.floor(diffDays / 365) > 1 ? 's' : '');
  return dd + '-' + mm + '-' + yyyy + ' (' + ago + ')';
};

const agoColor = (iso) => {
  if (!iso) return '#94A3B8';
  const diffDays = Math.floor((now - new Date(iso)) / (1000 * 60 * 60 * 24));
  if (diffDays > 180) return '#DC2626';
  if (diffDays > 90) return '#F59E0B';
  if (diffDays > 30) return '#2563EB';
  return '#16A34A';
};

const mapPriority = (p) => {
  const s = (p || '').toLowerCase();
  if (s.includes('highest') || s.includes('critica') || s.includes('blocker') || s.includes('muy alta') || s.includes('mas alta')) return 'Mas Alta';
  if (s.includes('lowest') || s.includes('muy baja') || s.includes('mas baja')) return 'Mas Baja';
  if (s.includes('high') || s === 'alta') return 'Alta';
  if (s.includes('medium') || s.includes('media') || s.includes('medio')) return 'Medio';
  if (s.includes('low') || s === 'baja') return 'Baja';
  return 'Medio';
};

const priorityStyle = (cat) => {
  if (cat === 'Mas Alta') return { color: '#DC2626', bg: '#FEF2F2' };
  if (cat === 'Alta') return { color: '#F59E0B', bg: '#FFFBEB' };
  if (cat === 'Medio') return { color: '#2563EB', bg: '#EFF6FF' };
  if (cat === 'Baja') return { color: '#64748B', bg: '#F1F5F9' };
  if (cat === 'Mas Baja') return { color: '#16A34A', bg: '#F0FDF4' };
  return { color: '#2563EB', bg: '#EFF6FF' };
};

const statusStyle = (status) => {
  const s = (status || '').toLowerCase();
  if (s.includes('done') || s.includes('finalizada') || s.includes('listo')) return { color: '#16A34A', bg: '#F0FDF4' };
  if (s.includes('progress') || s.includes('curso')) return { color: '#2563EB', bg: '#EFF6FF' };
  if (s.includes('impediment') || s.includes('bloq')) return { color: '#DC2626', bg: '#FEF2F2' };
  return { color: '#64748B', bg: '#F1F5F9' };
};

const priorityCounts = { 'Mas Alta': 0, 'Alta': 0, 'Medio': 0, 'Baja': 0, 'Mas Baja': 0 };
const byReporter = {};

for (const issue of issues) {
  const prioName = issue.fields.priority ? issue.fields.priority.name : 'Medium';
  const prioCat = mapPriority(prioName);
  priorityCounts[prioCat] = (priorityCounts[prioCat] || 0) + 1;

  const reporter = issue.fields.reporter ? issue.fields.reporter.displayName : 'Sin informador';
  if (!byReporter[reporter]) byReporter[reporter] = [];

  const pStyle = priorityStyle(prioCat);
  const statusName = issue.fields.status ? issue.fields.status.name : '-';
  const sStyle = statusStyle(statusName);
  const created = issue.fields.created || null;

  const issueType = issue.fields.issuetype ? issue.fields.issuetype.name : '-';

  byReporter[reporter].push({
    key: issue.key,
    tipo: issueType,
    titulo: issue.fields.summary || '-',
    prioCat: prioCat,
    prioColor: pStyle.color,
    prioBg: pStyle.bg,
    status: statusName,
    statusColor: sStyle.color,
    statusBg: sStyle.bg,
    created: created,
    createdStr: formatCreated(created),
    createdColor: agoColor(created)
  });
}

const sortedReporters = Object.entries(byReporter)
  .sort((a, b) => b[1].length - a[1].length);

const subject = 'Portal Pacientes \u{1F550} Tickets Backlog \u2014 ' + total + ' tickets | ' + fecha;

const cardHtml = (value, label, color, bg) => {
  return '<td width="20%" style="padding:4px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + bg + '; border-left:4px solid ' + color + '; border-radius:6px;"><tr><td style="padding:14px 12px;"><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:28px; font-weight:700; color:' + color + '; line-height:1;">' + value + '</div><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:9px; font-weight:700; letter-spacing:1px; color:#64748B; text-transform:uppercase; margin-top:4px;">' + label + '</div></td></tr></table></td>';
};

const cards = cardHtml(priorityCounts['Mas Alta'], '\u{1F534} MAS ALTA', '#DC2626', '#FEF2F2')
  + cardHtml(priorityCounts['Alta'], '\u{1F7E0} ALTA', '#F59E0B', '#FFFBEB')
  + cardHtml(priorityCounts['Medio'], '\u{1F535} MEDIO', '#2563EB', '#EFF6FF')
  + cardHtml(priorityCounts['Baja'], '⚪ BAJA', '#64748B', '#F1F5F9')
  + cardHtml(priorityCounts['Mas Baja'], '\u{1F7E2} MAS BAJA', '#16A34A', '#F0FDF4');

let reporterSections = '';
for (const [reporter, tickets] of sortedReporters) {
  const ticketRows = tickets.map((r) => {
    return '<tr>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:600; color:#0747A6; white-space:nowrap;">' + r.key + '</td>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; color:#475569; white-space:nowrap;">' + r.tipo + '</td>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B;">' + r.titulo + '</td>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; text-align:center;"><span style="background:' + r.prioBg + '; color:' + r.prioColor + '; padding:2px 8px; border-radius:12px; font-weight:700; font-size:11px; font-family:Segoe UI,Helvetica,Arial,sans-serif;">' + r.prioCat + '</span></td>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; text-align:center;"><span style="background:' + r.statusBg + '; color:' + r.statusColor + '; padding:2px 8px; border-radius:12px; font-weight:700; font-size:11px; font-family:Segoe UI,Helvetica,Arial,sans-serif;">' + r.status + '</span></td>'
      + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; color:' + r.createdColor + '; white-space:nowrap;">' + r.createdStr + '</td>'
      + '</tr>';
  }).join('');

  reporterSections += '<div style="padding:0 20px 16px;">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:4px;"><tr>'
    + '<td style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:14px; font-weight:700; color:#1E293B; padding:10px 0 6px;">\u{1F464} ' + reporter + '</td>'
    + '<td style="text-align:right; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; color:#64748B; padding:10px 0 6px;">' + tickets.length + ' ticket' + (tickets.length > 1 ? 's' : '') + '</td>'
    + '</tr></table>'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; background:#FFFFFF; border-radius:6px; overflow:hidden; box-shadow:0 1px 3px rgba(15,23,42,0.08);">'
    + '<thead><tr style="background:#F4F6F8;">'
    + '<th align="left" style="padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Ticket</th>'
    + '<th align="left" style="padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Tipo</th>'
    + '<th align="left" style="padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">T\u00edtulo</th>'
    + '<th align="center" style="padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Prioridad</th>'
    + '<th align="center" style="padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Estado</th>'
    + '<th align="left" style="padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Creado</th>'
    + '</tr></thead>'
    + '<tbody>' + ticketRows + '</tbody></table></div>';
}

const htmlBody = '<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; max-width:760px; margin:0 auto; background:#F4F6FB;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#0747A6;">'
  + '<tr><td style="padding:28px 28px;" valign="top">'
  + '<div style="color:#CFE2FF; font-size:11px; letter-spacing:3px; text-transform:uppercase; font-weight:700;">BUPA CHILE \u00B7 PORTAL PACIENTES</div>'
  + '<div style="color:#FFFFFF; font-size:20px; font-weight:700; margin-top:10px;">\u{1F550} Tickets Backlog</div>'
  + '<div style="color:#CFE2FF; font-size:13px; margin-top:6px;">' + total + ' ticket(s) en backlog \u00B7 ' + fecha + '</div>'
  + '</td></tr></table>'

  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:16px 20px;">'
  + '<tr>' + cards + '</tr></table>'

  + '<div style="padding:4px 20px 8px;"><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; font-weight:700; color:#64748B; letter-spacing:1.5px; text-transform:uppercase; border-bottom:2px solid #E2E8F0; padding-bottom:8px;">TICKETS POR INFORMADOR</div></div>'

  + reporterSections

  + '<div style="padding:14px 20px; font-size:11px; color:#94A3B8; text-align:center; border-top:1px solid #E2E8F0;">'
  + 'Generado autom\u00E1ticamente \u2014 WF-3 Tickets Backlog \u00B7 Portal Pacientes'
  + '</div></div>';

return [{ json: { subject, body: htmlBody } }];
